<?php
declare(strict_types=1);
defined('_JEXEC') or die;
use Joomla\CMS\Factory;use Joomla\CMS\Form\Field\ListField;use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Language\Text;use Joomla\Database\DatabaseInterface;use Joomla\Database\ParameterType;
class JFormFieldStatistic extends ListField{protected $type='Statistic';protected function getOptions():array{$options=parent::getOptions();$projectId=(int)$this->form->getValue('project_id',$this->group);if($projectId<1)return$options;$db=Factory::getContainer()->get(DatabaseInterface::class);$query=$db->getQuery(true)->select(['value.statistic_code','MAX(value.statistic_name_key) AS name_key'])->from($db->quoteName('#__joomleague_match_statistic_value','value'))->where('value.project_id=:project')->where('value.published=1')->where('value.numeric_value IS NOT NULL')->where('value.segment_key=0')->group('value.statistic_code')->order('value.statistic_code ASC')->bind(':project',$projectId,ParameterType::INTEGER);Factory::getLanguage()->load('com_joomleague',JPATH_SITE);foreach($db->setQuery($query)->loadObjectList()as$row)$options[]=HTMLHelper::_('select.option',(string)$row->statistic_code,Text::_((string)$row->name_key));return$options;}}
